import{Q as e,V as t,ht as n,it as r,nt as i,rt as a,tt as o,yt as s}from"./chunks/framework.K9m71cl2.js";import"./chunks/assets.-TFy-icx.js";var c=JSON.parse(`{"title":"🌐 教程篇-如何手动解锁网络限制","description":"","frontmatter":{},"headers":[],"relativePath":"guide/unlock_network.md","filePath":"guide/unlock_network.md","lastUpdated":0}`),l={name:`guide/unlock_network.md`};function u(t,c,l,u,d,f){let p=s(`ArticleMetadata`);return n(),o(`div`,null,[c[0]||=e(`h1`,{id:`🌐-教程篇-如何手动解锁网络限制`,tabindex:`-1`},[a(`🌐 教程篇-如何手动解锁网络限制 `),e(`a`,{class:`header-anchor`,href:`#🌐-教程篇-如何手动解锁网络限制`,"aria-label":`Permalink to “🌐 教程篇-如何手动解锁网络限制”`},`​`)],-1),r(p,{"file-time":`2026-08-02T02:45:36.000Z`}),c[1]||=i(`<blockquote><p>本工具网络解锁的本质原理即自动执行四条命令，因此即使不使用工具，你也可以手动输入几条命令来解锁噢易学生端的网络限制。本教程手把手教你操作。</p></blockquote><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to “适用场景”">​</a></h2><ul><li>在信息课上，学生端电脑被牢逝限制了网络</li><li>仅需恢复上网功能，不需要解锁其他限制</li><li>想了解解锁网络的底层原理</li></ul><h2 id="操作步骤" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤" aria-label="Permalink to “操作步骤”">​</a></h2><div class="info custom-block"><p class="custom-block-title">一：打开 CMD（命令提示符）</p><p><strong>操作示例：</strong></p><ol><li>点击任务栏搜索按钮（或按 <code>Win</code> 键）</li><li>输入 <code>cmd</code>，在搜索结果中找到&quot;命令提示符&quot; <img loading="lazy" src="/images/unlock_network/1.png" alt="搜索 cmd"></li><li>右键点击&quot;命令提示符&quot; → 选择&quot;以管理员身份运行&quot;，若弹出UAC用户账户控制，请点击&quot;是&quot;确认 <img loading="lazy" src="/images/unlock_network/2.png" alt="以管理员身份运行"></li><li>出现 CMD 黑色窗口即成功 <img loading="lazy" src="/images/unlock_network/3.png" alt="CMD 成功打开"></li></ol><blockquote><p>机房电脑通常默认登录管理员账户，直接 Win+R 运行 cmd 就是管理员权限，无需额外操作。</p></blockquote></div><div class="info custom-block"><p class="custom-block-title">二：停止 MMPC（学生端根服务）</p><div class="language-batch line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">batch</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">sc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> stop mmpc</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>停止学生端根服务（MMPC），这是管控学生端的中心服务（该服务没什么实质性的管控，最大的作用为实时监控学生端是否被偷偷关闭，若检测到学生端被关闭，就会自动重启相关进程。所以这是解锁的第一步）</p><p><strong>操作示例：</strong></p><ol><li>在 CMD 中输入命令 <code>sc stop mmpc</code> 并回车 <img loading="lazy" src="/images/unlock_network/4.png" alt="输入 sc stop mmpc"></li><li>显示 <code>STATE: 1 STOPPED</code> 即表示执行成功。命令不区分大小写 <img loading="lazy" src="/images/unlock_network/5.png" alt="执行成功"></li></ol></div><div class="info custom-block"><p class="custom-block-title">三：停止 OeNetlimit（网络限制服务）</p><div class="language-batch line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">batch</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">sc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> stop oenetlimit</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>停止网络过滤和限制服务，解除驱动级服务对网络的限制。</p><p><strong>操作示例：</strong></p><ol><li>在 CMD 窗口中输入 <code>sc stop oenetlimit</code> 并回车 <img loading="lazy" src="/images/unlock_network/6.png" alt="输入 sc stop oenetlimit"></li><li>显示 <code>STATE: 1 STOPPED</code>（或 <code>STOP_PENDING</code>）即表示执行成功</li></ol></div><div class="info custom-block"><p class="custom-block-title">四：结束 DeviceControl_x64.exe（设备控制进程）</p><div class="language-batch line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">batch</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">taskkill</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /f /im DeviceControl_x64.exe</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>结束设备控制进程，解除网络和程序限制</p><p><strong>操作示例：</strong></p><ol><li>右键任务栏空白处 → 选择&quot;任务管理器&quot; <img loading="lazy" src="/images/unlock_network/7.png" alt="打开任务管理器"></li><li>点击左下角的&quot;详细信息&quot;展开完整列表 <img loading="lazy" src="/images/unlock_network/8.png" alt="右键任务栏打开任务管理器"></li><li>在进程列表中找到 <code>DeviceControl_x64.exe</code> → 右键 → 选择&quot;结束任务&quot; <img loading="lazy" src="/images/unlock_network/9.png" alt="点击详细信息"></li></ol></div><p>总共就 <strong>4 个步骤</strong>，逐步进行即可，十几秒就能搞定。</p><h2 id="验证解锁成果" tabindex="-1">验证解锁成果 <a class="header-anchor" href="#验证解锁成果" aria-label="Permalink to “验证解锁成果”">​</a></h2><p>解锁后，尝试以下操作验证网络是否恢复：</p><ol><li>打开浏览器，访问任意网站（如 <code>baidu.com</code>）</li><li>如果能正常加载，说明网络已解锁 ✅</li><li>如果仍然受限，尝试 <strong>重启浏览器</strong> 或检查是否还有其他限制</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to “常见问题”">​</a></h2><div class="tip custom-block"><p class="custom-block-title">关闭服务时报错</p><h3 id="q-执行-sc-stop-提示服务名无效" tabindex="-1">Q：执行 <code>sc stop</code> 提示服务名无效？ <a class="header-anchor" href="#q-执行-sc-stop-提示服务名无效" aria-label="Permalink to “Q：执行 sc stop 提示服务名无效？”">​</a></h3><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[SC] OpenService FAILED 1060: 指定的服务未安装。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这说明你输错了，请重新输。</p><h3 id="q-执行-sc-stop-提示服务未启动" tabindex="-1">Q：执行 <code>sc stop</code> 提示服务未启动？ <a class="header-anchor" href="#q-执行-sc-stop-提示服务未启动" aria-label="Permalink to “Q：执行 sc stop 提示服务未启动？”">​</a></h3><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[SC] OpenService FAILED 1062: 指定的服务未启动。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这说明该服务未启动/已被关闭，可能是你重复输入了同一条命令，且已经执行成功过了，请去执行下一步吧。</p><h3 id="q-执行-sc-stop-拒绝访问" tabindex="-1">Q：执行 <code>sc stop</code> 拒绝访问？ <a class="header-anchor" href="#q-执行-sc-stop-拒绝访问" aria-label="Permalink to “Q：执行 sc stop 拒绝访问？”">​</a></h3><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[SC] OpenService 失败 5: 拒绝访问。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这说明你未以管理员身份运行 <code>CMD</code>，请重新以管理员身份运行 <code>CMD</code></p></div><h3 id="q-重启电脑后网络又被限制了" tabindex="-1">Q：重启电脑后网络又被限制了？ <a class="header-anchor" href="#q-重启电脑后网络又被限制了" aria-label="Permalink to “Q：重启电脑后网络又被限制了？”">​</a></h3><p>这是正常的——学校机房将计算机设为了每次重启时还原，也就是说每次重启都不会保留你的任何内容，我也没办法，只能每次上课时进行解锁。</p><h3 id="q-解锁后任务栏的网络图标仍然显示-无internet-或黄色感叹号" tabindex="-1">Q：解锁后任务栏的网络图标仍然显示&quot;无Internet&quot;或黄色感叹号？ <a class="header-anchor" href="#q-解锁后任务栏的网络图标仍然显示-无internet-或黄色感叹号" aria-label="Permalink to “Q：解锁后任务栏的网络图标仍然显示&quot;无Internet&quot;或黄色感叹号？”">​</a></h3><p>这是正常现象。学生端网络限制解除后，系统网络状态指示可能需要一段时间才能刷新。<strong>请直接打开浏览器访问任意网站</strong>，你会发现网络实际上已经恢复正常了，不需要理会网络图标的显示状态。</p><h3 id="q-终止后又自动恢复了怎么办" tabindex="-1">Q：终止后又自动恢复了怎么办？ <a class="header-anchor" href="#q-终止后又自动恢复了怎么办" aria-label="Permalink to “Q：终止后又自动恢复了怎么办？”">​</a></h3><p>这说明你没有成功的关闭学生端根服务，请尝试重新关闭。</p>`,20)])}var d=t(l,[[`render`,u]]);export{c as __pageData,d as default};